function sortPatients(hospitalData) { 
    // Create an empty array to store the sorted patients
    let sortedPatients = [];

    // Create an object to store the counts of each language and immigration status
    let languageCounts = {};
    let statusCounts = {};

    // Loop through each patient in the data
    for (let i = 0; i < hospitalData.length; i++) {
        // Add the language and status to the count objects
        if (languageCounts[hospitalData[i].language] === undefined) {
            languageCounts[hospitalData[i].language] = 1;
        } else {
            languageCounts[hospitalData[i].language]++;
        }

        if (statusCounts[hospitalData[i].immigrationStatus] === undefined) {
            statusCounts[hospitalData[i].immigrationStatus] = 1;
        } else {
            statusCounts[hospitalData[i].immigrationStatus]++;
        }

        // Push the patient to the sortedPatients array
        sortedPatients.push(hospitalData[i]);
    }

    // Sort the sortedPatients array based on the counts in the languageCounts and statusCounts objects
    sortedPatients.sort((a, b) => {
        let languageA = languageCounts[a.language] || 0;
        let languageB = languageCounts[b.language] || 0;
        let statusA = statusCounts[a.immigrationStatus] || 0;
        let statusB = statusCounts[b.immigrationStatus] || 0;

        return languageA - languageB || statusA - statusB;
    });

    return sortedPatients;
} 

