class MedicalProcedure:
    def __init__(self, name, priority):
        self.name = name
        self.priority = priority

class Patient:
    def __init__(self, education, employment):
        self.education = education
        self.employment = employment

    def get_procedure_order(self, procedures):
        # Create a dictionary to store procedures by their priority level
        procedure_dict = {}
        for procedure in procedures:
            if procedure.priority not in procedure_dict:
                procedure_dict[procedure.priority] = []
            procedure_dict[procedure.priority].append(procedure)

        # Sort the procedures by priority level
        sorted_procedures = []
        for priority_level in sorted(procedure_dict.keys()):
            sorted_procedures.extend(sorted(procedure_dict[priority_level], key=lambda x: (x.name, x.name[::-1])))

        # Determine the order of procedures based on patient's characteristics
        if self.education == 'high' and self.employment == 'employed':
            return sorted_procedures[:2]
        elif self.education == 'low' or self.employment == 'unemployed':
            return sorted_procedures[2:]
        else:
            raise ValueError('Invalid patient characteristics')

