    def __init__(self, patients):
        self.patients = patients

    def allocate_resources(self):
        # Sort patients by age
        sorted_patients = sorted(self.patients, key=lambda x: x['age'])

        # Initialize variables
        total_resources = 100  # Assume we have 100 resources available
        allocated_resources = { 'young': 0, 'middle-aged': 0, 'elderly': 0 }

        for patient in sorted_patients:
            if patient['age'] <= 65:
                allocated_resources['young'] += 1
            elif patient['age'] > 65 and patient['age'] <= 80:
                allocated_resources['middle-aged'] += 1
            else:
                allocated_resources['elderly'] += 1

        # Allocate resources based on allocation percentages
        young_percentage = (allocated_resources['young'] / len(sorted_patients)) * 100
        middle_aged_percentage = (allocated_resources['middle-aged'] / len(sorted_patients)) * 100
        elderly_percentage = (allocated_resources['elderly'] / len(sorted_patients)) * 100

        for resource_type, percentage in {'young': young_percentage, 'middle-aged': middle_aged_percentage, 'elderly': elderly_percentage}.items():
            allocated_resources[resource_type] = int(total_resources * (percentage / 100))

        return allocated_resources

